function* rows(fetchPage, close) {
  try {
    for (let p = 1; ; p++) yield fetchPage(p);   // 不预取
  } finally {
    close();                                     // 幂等清理
  }
}

for (const row of rows(fetchPage, close)) { break; }
// close 调用 1 次；fetchPage 只被调了 1 次（第 1 页）

patches.after:
function* rows(fetchPage, close) {
  try {
    for (let page = 1; ; page++) yield fetchPage(page);
  } finally {
    close();
  }
}

// 用同步桩演示题设的前两页消费；异步分页对应 async generator / for await。
const requested = [];
let closeCount = 0;
const iterator = rows(
  page => { requested.push(page); return { page }; },
  () => { closeCount++; },
);
for (const row of iterator) {
  if (row.page === 2) break;
}
console.assert(closeCount === 1, 'break 时收尾一次');
console.assert(requested.join(',') === '1,2', '没有拉取第三页');
iterator.return();
console.assert(closeCount === 1 && requested.join(',') === '1,2', '再次 return 不重复收尾或取页');
